package com.ellenco.platform.domain;
import com.fasterxml.jackson.annotation.JsonIgnore;import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="inventario_itens")public class InventoryCountItem{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@JsonIgnore@ManyToOne(optional=false)@JoinColumn(name="inventario_id")private InventoryCount inventario;@ManyToOne(optional=false)@JoinColumn(name="saldo_id")private StockBalance saldo;@Column(nullable=false,precision=19,scale=2)private BigDecimal saldoSistema;@Column(precision=19,scale=2)private BigDecimal quantidadeContada;@Column(precision=19,scale=2)private BigDecimal divergencia;private String motivo;private boolean contado=false;
 public Long getId(){return id;}public InventoryCount getInventario(){return inventario;}public void setInventario(InventoryCount v){inventario=v;}public StockBalance getSaldo(){return saldo;}public void setSaldo(StockBalance v){saldo=v;}public BigDecimal getSaldoSistema(){return saldoSistema;}public void setSaldoSistema(BigDecimal v){saldoSistema=v;}public BigDecimal getQuantidadeContada(){return quantidadeContada;}public void setQuantidadeContada(BigDecimal v){quantidadeContada=v;}public BigDecimal getDivergencia(){return divergencia;}public void setDivergencia(BigDecimal v){divergencia=v;}public String getMotivo(){return motivo;}public void setMotivo(String v){motivo=v;}public boolean isContado(){return contado;}public void setContado(boolean v){contado=v;}
}
